package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

// prevent unused import error
var _ = decimal.NewFromInt

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"  // PIC X len=1 = "N"
var WsLeapFlag string = "N" // PIC X len=1 = "N"
var WsQ int64 = 0           // PIC 9(4) len=4 = 0
var WsR4 int64 = 0          // PIC 9(3) len=3 = 0
var WsR100 int64 = 0        // PIC 9(3) len=3 = 0
var WsR400 int64 = 0        // PIC 9(3) len=3 = 0
var WsMaxDay int64 = 0      // PIC 99 len=2 = 0
var WsValid int64 = 0       // PIC 99 len=2 = 0
var WsBadMonth int64 = 0    // PIC 99 len=2 = 0
var WsBadDay int64 = 0      // PIC 99 len=2 = 0

var dateRec DateRec

// file handling
var dateFile *os.File
var dateScanner *bufio.Scanner

func isInputDone() bool {
	return WsEofFlag == "Y"
}
func isLeap() bool {
	return WsLeapFlag == "Y"
}

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func truncPIC9(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := pow10(digits)
	// keep low-order digits, preserve sign similar to COBOL
	// for positive, simple modulo
	if v >= 0 {
		return v % mod
	}
	// for negative, take modulo and keep sign
	neg := -v % mod
	if neg == 0 {
		return 0
	}
	return -neg
}

func formatPIC9(v int64, digits int) string {
	// high-order truncation then zero pad
	tv := truncPIC9(v, digits)
	if tv < 0 {
		tv = -tv // not expected for these fields but handle
	}
	s := fmt.Sprintf("%d", tv)
	if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	} else if len(s) > digits {
		s = s[len(s)-digits:]
	}
	return s
}

func parsePIC9(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var v int64 = 0
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			v = v*10 + int64(ch-'0')
		}
	}
	return v
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func READPARA() {
	if dateScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if dateScanner.Scan() {
		line := dateScanner.Text()
		// remove possible \r from CRLF
		if strings.HasSuffix(line, "\r") {
			line = strings.TrimSuffix(line, "\r")
		}
		if len(line) < 12 {
			line = line + strings.Repeat(" ", 12-len(line))
		} else if len(line) > 12 {
			line = line[:12]
		}
		dateRec.DtId = line[0:4]
		dateRec.DtYyyy = parsePIC9(line[4:8])
		dateRec.DtMm = parsePIC9(line[8:10])
		dateRec.DtDd = parsePIC9(line[10:12])
	} else {
		WsEofFlag = "Y"
	}
}

func LEAPPARA() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	// COBOL DIVIDE truncates toward zero; all positive so integer division
	WsQ = truncPIC9(dateRec.DtYyyy/4, 4)
	WsR4 = truncPIC9(dateRec.DtYyyy%4, 3)
	WsQ = truncPIC9(dateRec.DtYyyy/100, 4)
	WsR100 = truncPIC9(dateRec.DtYyyy%100, 3)
	WsQ = truncPIC9(dateRec.DtYyyy/400, 4)
	WsR400 = truncPIC9(dateRec.DtYyyy%400, 3)
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYSPARA() {
	switch dateRec.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = truncPIC9(29, 2)
		} else {
			WsMaxDay = truncPIC9(28, 2)
		}
	case 4, 6, 9, 11:
		WsMaxDay = truncPIC9(30, 2)
	default:
		WsMaxDay = truncPIC9(31, 2)
	}
}

func PROCESSPARA() {
	LEAPPARA()
	if dateRec.DtMm < 1 || dateRec.DtMm > 12 {
		WsBadMonth = truncPIC9(WsBadMonth+1, 2)
		// DISPLAY DT-ID " BAD MONTH " DT-MM
		fmt.Fprint(os.Stdout, padRight(dateRec.DtId, 4))
		fmt.Fprint(os.Stdout, " BAD MONTH ")
		fmt.Fprint(os.Stdout, formatPIC9(dateRec.DtMm, 2))
		fmt.Fprintln(os.Stdout)
	} else {
		DAYSPARA()
		if dateRec.DtDd < 1 || dateRec.DtDd > WsMaxDay {
			WsBadDay = truncPIC9(WsBadDay+1, 2)
			fmt.Fprint(os.Stdout, padRight(dateRec.DtId, 4))
			fmt.Fprint(os.Stdout, " BAD DAY ")
			fmt.Fprint(os.Stdout, formatPIC9(dateRec.DtDd, 2))
			fmt.Fprint(os.Stdout, " MAX ")
			fmt.Fprint(os.Stdout, formatPIC9(WsMaxDay, 2))
			fmt.Fprintln(os.Stdout)
		} else {
			WsValid = truncPIC9(WsValid+1, 2)
			fmt.Fprint(os.Stdout, padRight(dateRec.DtId, 4))
			fmt.Fprint(os.Stdout, " VALID ")
			fmt.Fprint(os.Stdout, formatPIC9(dateRec.DtYyyy, 4))
			fmt.Fprint(os.Stdout, "-")
			fmt.Fprint(os.Stdout, formatPIC9(dateRec.DtMm, 2))
			fmt.Fprint(os.Stdout, "-")
			fmt.Fprint(os.Stdout, formatPIC9(dateRec.DtDd, 2))
			fmt.Fprintln(os.Stdout)
		}
	}
	READPARA()
}

func main() {
	// OPEN INPUT DATE-FILE
	var err error
	dateFile, err = os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty
		dateScanner = nil
		WsEofFlag = "N"
	} else {
		dateScanner = bufio.NewScanner(dateFile)
		// allow long lines
	}
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	if dateFile != nil {
		dateFile.Close()
	}
	// DISPLAY "VALID: " WS-VALID " BAD MONTH: " WS-BAD-MONTH " BAD DAY: " WS-BAD-DAY
	fmt.Fprint(os.Stdout, "VALID: ")
	fmt.Fprint(os.Stdout, formatPIC9(WsValid, 2))
	fmt.Fprint(os.Stdout, " BAD MONTH: ")
	fmt.Fprint(os.Stdout, formatPIC9(WsBadMonth, 2))
	fmt.Fprint(os.Stdout, " BAD DAY: ")
	fmt.Fprint(os.Stdout, formatPIC9(WsBadDay, 2))
	fmt.Fprintln(os.Stdout)
}
